def process(boston_data, chatham_data, amherst_data, ashburnham_data):
    results = []

    # Extract 2020 summer data for each region
    for region_name, df in [('Boston', boston_data), ('Chatham', chatham_data), 
                             ('Amherst', amherst_data), ('Ashburnham', ashburnham_data)]:
